let databaseContextPromise;
function getElectronBridge() {
  const bridge = window.electron;
  if (!bridge?.invoke) {
    throw new Error("Electron IPC bridge is not available.");
  }
  return bridge;
}
async function createDatabaseContext() {
  const bridge = getElectronBridge();
  const callback = async (sql2, params, method) => {
    const result = await bridge.invoke("db:execute", { sql: sql2, params, method });
    return result;
  };
  return {
    execute: callback,
    db: drizzle(callback, { schema })
  };
}
async function getDatabaseContext() {
  if (!databaseContextPromise) {
    databaseContextPromise = createDatabaseContext();
  }
  return databaseContextPromise;
}
async function executePersistedMutation(operation) {
  const context2 = await getDatabaseContext();
  return operation(context2);
}
async function pingDatabase() {
  const context2 = await getDatabaseContext();
  return context2.execute("SELECT 1 AS value", [], "all");
}
