function createWorkflowDefinition(title) {
  return {
    nodes: [
      {
        id: `${title}-start`,
        type: "input",
        position: { x: 40, y: 120 },
        data: {
          label: "Start",
          prompt: "Collect the incoming request and normalize variables.",
          kind: "start"
        }
      },
      {
        id: `${title}-agent`,
        position: { x: 280, y: 120 },
        data: {
          label: "Agent Step",
          prompt: `Generate output for ${title}.`,
          kind: "agent"
        }
      },
      {
        id: `${title}-output`,
        position: { x: 540, y: 120 },
        data: {
          label: "Output",
          prompt: "Return the final response payload.",
          kind: "output"
        }
      }
    ],
    edges: [
      { id: `${title}-edge-1`, source: `${title}-start`, target: `${title}-agent` },
      { id: `${title}-edge-2`, source: `${title}-agent`, target: `${title}-output` }
    ],
    viewport: { x: 0, y: 0, zoom: 1 }
  };
}
function createSkillFiles(skillName) {
  return [
    {
      path: "SKILL.md",
      language: "md",
      kind: "file",
      content: `---
name: ${JSON.stringify(skillName)}
description: ${JSON.stringify(`Describe what ${skillName} does and when to use it.`)}
---

## Purpose

Describe the skill intent, triggers, and limits here.
`
    },
    {
      path: "references",
      language: "txt",
      kind: "directory",
      content: ""
    },
    {
      path: "references/README.md",
      language: "md",
      kind: "file",
      content: `# References

Capture related docs, notes, or external links for ${skillName}.`
    },
    {
      path: "assets",
      language: "txt",
      kind: "directory",
      content: ""
    },
    {
      path: "assets/.gitkeep",
      language: "txt",
      kind: "file",
      content: ""
    },
    {
      path: "scripts",
      language: "txt",
      kind: "directory",
      content: ""
    },
    {
      path: "scripts/main.ts",
      language: "ts",
      kind: "file",
      executable: true,
      content: [
        "export async function main(input: unknown) {",
        "  return { ok: true, input }",
        "}",
        ""
      ].join("\n")
    },
    {
      path: "other",
      language: "txt",
      kind: "directory",
      content: ""
    },
    {
      path: "other/notes.md",
      language: "md",
      kind: "file",
      content: `# Notes

Add extra snippets or implementation notes for ${skillName}.`
    }
  ];
}
function createDocumentPages(title) {
  return [
    { id: `${title}-guides`, title: "guides", content: "", type: "folder", parentId: null },
    { id: `${title}-overview`, title: `${title}-overview.md`, content: `# ${title}

## Overview

${title} overview and purpose.
`, type: "document", parentId: `${title}-guides` },
    { id: `${title}-details`, title: `${title}-details.md`, content: `# ${title} Details

${title} implementation details and linked resources.
`, type: "document", parentId: `${title}-guides` }
  ];
}
function createDocumentGraph(pages) {
  return pages.length > 1 ? [{ id: `${pages[0].id}-${pages[1].id}`, source: pages[0].title, target: pages[1].title, label: "supports", status: "approved", confidence: 0.92 }] : [];
}
function createDocumentSettings() {
  return {
    isPublic: false,
    includeInLlmsTxt: true
  };
}
